CREATE TABLE roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO roles(name) VALUES ('super_admin'),('admin'),('team_member'),('customer');
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO permissions(name) VALUES ('system.manage'),('projects.manage'),('projects.assigned'),('billing.manage');
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('super_admin','admin','team_member','customer') NOT NULL DEFAULT 'customer', company VARCHAR(190) DEFAULT '', phone VARCHAR(40) DEFAULT '', timezone VARCHAR(60) DEFAULT 'UTC', country VARCHAR(80) DEFAULT '', active TINYINT NOT NULL DEFAULT 1, verified_at DATETIME NULL, notification_email TINYINT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_roles (user_id INT UNSIGNED NOT NULL, role_id INT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE plans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, price INT UNSIGNED NOT NULL DEFAULT 0, websites INT NOT NULL, keywords INT NOT NULL, crawl_pages INT NOT NULL, reports INT NOT NULL, ai_requests INT NOT NULL DEFAULT 0, team_members INT NOT NULL DEFAULT 0, white_label TINYINT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO plans(slug,name,price,websites,keywords,crawl_pages,reports,ai_requests,team_members,white_label) VALUES ('free','Free',0,1,50,100,1,0,0,0),('starter','Starter',199900,3,250,1000,10,100,0,0),('growth','Growth',599900,10,1000,5000,-1,500,0,0),('agency','Agency',1499900,50,5000,25000,-1,2000,20,1);
CREATE TABLE plan_features (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, plan_id INT UNSIGNED NOT NULL, name VARCHAR(80) NOT NULL, value TEXT, UNIQUE(plan_id,name), FOREIGN KEY(plan_id) REFERENCES plans(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE subscriptions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, plan_id INT UNSIGNED NOT NULL, status ENUM('active','cancelled','expired') DEFAULT 'active', starts_at DATETIME NOT NULL, ends_at DATETIME NULL, cancelled_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,status,ends_at), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(plan_id) REFERENCES plans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE websites (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, domain VARCHAR(500) NOT NULL, domain_hash CHAR(64) NOT NULL, country VARCHAR(80) DEFAULT 'India', language VARCHAR(40) DEFAULT 'en', search_engine VARCHAR(30) DEFAULT 'google', timezone VARCHAR(60) DEFAULT 'UTC', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,domain_hash), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE website_settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, name VARCHAR(80) NOT NULL, value TEXT, UNIQUE(website_id,name), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE team_members (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, website_id INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,website_id), FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE crawl_jobs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, status ENUM('queued','running','completed','failed') DEFAULT 'queued', max_pages INT UNSIGNED NOT NULL, processed INT UNSIGNED DEFAULT 0, robots TEXT, sitemap TEXT, error TEXT, heartbeat DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME NULL, INDEX(status,heartbeat), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE crawl_urls (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job_id INT UNSIGNED NOT NULL, url TEXT NOT NULL, url_hash CHAR(64) NOT NULL, status ENUM('queued','done','failed','blocked') DEFAULT 'queued', error TEXT, UNIQUE(job_id,url_hash), INDEX(job_id,status), FOREIGN KEY(job_id) REFERENCES crawl_jobs(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, job_id INT UNSIGNED NOT NULL, url TEXT NOT NULL, url_hash CHAR(64) NOT NULL, http_status SMALLINT NOT NULL, title TEXT, description TEXT, h1 TEXT, h2 TEXT, word_count INT DEFAULT 0, image_count INT DEFAULT 0, missing_alt INT DEFAULT 0, internal_links JSON, external_links JSON, canonical TEXT, robots TEXT, schema_count INT DEFAULT 0, og_count INT DEFAULT 0, noindex TINYINT DEFAULT 0, load_ms INT DEFAULT 0, score INT DEFAULT 0, details JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(job_id,url_hash), INDEX(website_id,job_id), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE, FOREIGN KEY(job_id) REFERENCES crawl_jobs(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE seo_audits (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, job_id INT UNSIGNED NOT NULL UNIQUE, score INT NOT NULL, technical INT NOT NULL, onpage INT NOT NULL, content INT NOT NULL, performance INT NOT NULL, linking INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE, FOREIGN KEY(job_id) REFERENCES crawl_jobs(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE seo_issue_types (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, title VARCHAR(190) NOT NULL, severity VARCHAR(30) NOT NULL, explanation TEXT, recommendation TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE seo_issues (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, audit_id INT UNSIGNED NOT NULL, page_id BIGINT UNSIGNED NULL, code VARCHAR(80) NOT NULL, title VARCHAR(190) NOT NULL, severity VARCHAR(30) NOT NULL, category VARCHAR(30) NOT NULL, explanation TEXT, recommendation TEXT, url TEXT, status ENUM('open','resolved','ignored') DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(website_id,status,severity), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE, FOREIGN KEY(audit_id) REFERENCES seo_audits(id) ON DELETE CASCADE, FOREIGN KEY(page_id) REFERENCES pages(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE keyword_groups (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, UNIQUE(website_id,name), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE keywords (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, keyword VARCHAR(190) NOT NULL, country VARCHAR(80) DEFAULT 'India', language VARCHAR(40) DEFAULT 'en', search_engine VARCHAR(30) DEFAULT 'google', device ENUM('desktop','mobile') DEFAULT 'desktop', target_url VARCHAR(500) DEFAULT '', intent VARCHAR(80) DEFAULT '', tags VARCHAR(190) DEFAULT '', search_volume INT UNSIGNED NULL, difficulty DECIMAL(5,2) NULL, cpc DECIMAL(10,2) NULL, source VARCHAR(30) DEFAULT 'manual', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(website_id,keyword,country,device), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE keyword_rankings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, keyword_id INT UNSIGNED NOT NULL, date DATE NOT NULL, position INT UNSIGNED NULL, url TEXT, source VARCHAR(40) NOT NULL, UNIQUE(keyword_id,date), FOREIGN KEY(keyword_id) REFERENCES keywords(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE competitors (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, domain VARCHAR(500) NOT NULL, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE competitor_keywords (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, competitor_id INT UNSIGNED NOT NULL, keyword VARCHAR(190) NOT NULL, position INT NULL, source VARCHAR(30) DEFAULT 'manual', FOREIGN KEY(competitor_id) REFERENCES competitors(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE backlinks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, source_url VARCHAR(1000) NOT NULL, target_url VARCHAR(1000) NOT NULL, anchor VARCHAR(255) DEFAULT '', domain VARCHAR(255) NOT NULL, domain_rating DECIMAL(5,2) NULL, follow ENUM('follow','nofollow') DEFAULT 'follow', first_seen DATE NOT NULL, last_seen DATE NOT NULL, status ENUM('active','lost') DEFAULT 'active', source VARCHAR(30) DEFAULT 'manual', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(website_id,status), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE content_projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, topic VARCHAR(190) NOT NULL, keyword VARCHAR(190) NOT NULL, audience VARCHAR(190) DEFAULT '', country VARCHAR(80) DEFAULT '', language VARCHAR(40) DEFAULT 'en', status VARCHAR(30) DEFAULT 'draft', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE content_briefs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, content_project_id INT UNSIGNED NOT NULL, content MEDIUMTEXT NOT NULL, source VARCHAR(30) DEFAULT 'manual', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(content_project_id) REFERENCES content_projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_conversations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, website_id INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conversation_id INT UNSIGNED NOT NULL, role VARCHAR(20) NOT NULL, content MEDIUMTEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(conversation_id) REFERENCES ai_conversations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_usage (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, website_id INT UNSIGNED NOT NULL, status VARCHAR(20) NOT NULL, tokens INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,created_at), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE seo_tasks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, title VARCHAR(190) NOT NULL, url TEXT, issue_id BIGINT UNSIGNED NULL, priority ENUM('critical','high','medium','low') DEFAULT 'medium', assigned_user INT UNSIGNED NULL, due_date DATE NULL, status ENUM('open','in_progress','waiting','completed','rejected') DEFAULT 'open', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(issue_id), INDEX(website_id,status), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE, FOREIGN KEY(assigned_user) REFERENCES users(id), FOREIGN KEY(issue_id) REFERENCES seo_issues(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE automation_rules (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, code VARCHAR(80) NOT NULL, enabled TINYINT DEFAULT 1, UNIQUE(website_id,code), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE internal_link_suggestions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, source_url VARCHAR(1000) NOT NULL, target_url VARCHAR(1000) NOT NULL, anchor VARCHAR(190) NOT NULL, status ENUM('suggested','accepted','rejected','implemented') DEFAULT 'suggested', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE reports (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, title VARCHAR(190) NOT NULL, snapshot JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,created_at), FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE coupons (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, type ENUM('percentage','fixed') NOT NULL, amount INT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, usage_limit INT UNSIGNED NOT NULL, per_user_limit INT UNSIGNED DEFAULT 1, active TINYINT DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, plan_id INT UNSIGNED NOT NULL, order_id VARCHAR(100) NULL UNIQUE, provider_payment_id VARCHAR(100) NULL UNIQUE, amount INT UNSIGNED NOT NULL, currency CHAR(3) DEFAULT 'INR', status ENUM('pending','paid','failed') DEFAULT 'pending', coupon_id INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, paid_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(plan_id) REFERENCES plans(id), FOREIGN KEY(coupon_id) REFERENCES coupons(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE coupon_usage (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, coupon_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, payment_id INT UNSIGNED NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(coupon_id) REFERENCES coupons(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(payment_id) REFERENCES payments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE invoices (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id INT UNSIGNED NOT NULL UNIQUE, number VARCHAR(60) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(payment_id) REFERENCES payments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE human_service_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, website_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, service VARCHAR(100) NOT NULL, budget INT UNSIGNED NOT NULL, description TEXT NOT NULL, priority ENUM('high','medium','low') DEFAULT 'medium', assigned_user INT UNSIGNED NULL, status ENUM('new','assigned','in_progress','waiting_for_customer','completed','cancelled') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(assigned_user) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, message VARCHAR(500) NOT NULL, path VARCHAR(500) NOT NULL, read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,read_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE email_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, recipient VARCHAR(190) NOT NULL, subject VARCHAR(255) NOT NULL, body MEDIUMTEXT NOT NULL, status ENUM('queued','sending','sent','failed') DEFAULT 'queued', attempts INT DEFAULT 0, error TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sent_at DATETIME NULL, INDEX(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE api_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, provider VARCHAR(60) NOT NULL, status VARCHAR(30), message TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE system_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, level VARCHAR(20) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(100) NOT NULL, context JSON, ip VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings (name VARCHAR(100) PRIMARY KEY, value MEDIUMTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO settings(name,value) VALUES ('registration','true'),('maintenance','false'),('site_name','"SEO AutoPilot"'),('require_verification','false'),('score_weights','{"technical":30,"onpage":30,"content":20,"performance":10,"linking":10}'),('crawl_delay_ms','1000'),('trial_days','0');
CREATE TABLE auth_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, purpose ENUM('reset','verify','remember') NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE rate_limits (bucket CHAR(64) PRIMARY KEY, hits INT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
